Template.Design:
@using MediaWiz.Forums.Extensions
@using Umbraco.Cms.Core.Models.PublishedContent
@using Umbraco.Cms.Core.Security
@using Umbraco.Extensions
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage
@inject IMemberManager _memberManager
@{
    Layout = "mediawizMaster.cshtml";

    // Replace the layout with your own master template.

    // You will also need to add the section definitions for Styles and Scripts to your master template
    // For example:

    // @await RenderSectionAsync("MediaWizHeader", required:false) //should go in your head section
    // @await RenderSectionAsync("MediaWizScripts", required:false) //should go just above your closing body tag

}
@{

    IList<string> roles = new List<string>();
    var allowimages = Model.Value<bool>("allowImages", fallback: Fallback.ToAncestors);
    var ForumUrl = Umbraco.GetDictionaryValueOrDefault("Forums.ForumUrl", "/").TrimEnd('/');
    string returnUrl = null;
    if (TempData["returnUrl"] != null)
    {
        returnUrl = (string)TempData["returnUrl"];
        TempData["returnUrl"] = null;
    }
}


@section MediaWizHeader {
    @if (returnUrl != null)
    {
        <meta http-equiv="Refresh" content="3;url=@returnUrl" />
    }

    <link rel="stylesheet" type="text/css" href="~/css/forum.min.css">
    <link rel="stylesheet" type="text/css" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.8.3/font/bootstrap-icons.css">
    <link rel="stylesheet" type="text/css" href="https://cdnjs.cloudflare.com/ajax/libs/animate.css/3.2.3/animate.min.css" />
    <style>
        #mediawiz-forums h3 {
            color: #527AB3;
        }

        .alert {
            position: relative;
        }

        .alert .close {
            position: absolute;
            top: 5px;
            right: 5px;
            font-size: 1em;
        }

        .alert .fa {
            margin-right: .3em;
        }
    </style>
    <renderstoredcontent asp-key="css-block"></renderstoredcontent>
}

<div class="breadcrumb mt-3 ">
    <header class="header flex-fill flex-row justify-content-between bg-white text-dark border-light rounded-3">
        @await Component.InvokeAsync("Navigation", new { Template = "Breadcrumb" })
    </header>
</div>

<div class="forum container">
    <div class="rounded-3">
        <div class="sidebar p-3 bg-white text-dark" id="sidebar">
            <nav>
                <span class="h6">@await Component.InvokeAsync("ForumMembership", new { Template = "LoginStatus" })</span>
                <a href="@ForumUrl" class="nav-link" title="View List of Forums"><i class="fs-5 bi-folder me-3"></i><span class="d-none d-sm-none d-md-inline">Forums</span></a>
                <a href="/active-topics" class="nav-link" title="View Active Topics"><i class="fs-5 bi-list me-3"></i><span class="d-none d-sm-none d-md-inline">Topics</span></a>
                @if (_memberManager.IsLoggedIn())
                {
                    <a href="/members" class="nav-link" title="View list of Forum members"><i class="fs-5 bi-people me-3"></i><span class="d-none d-sm-none d-md-inline">Members</span></a>
                }
                <a href="/forumsearch" class="nav-link" title="Search forum posts"><i class="fs-5 bi-search me-3"></i><span class="d-none d-sm-none d-md-inline">Search</span></a>
                @if (_memberManager.IsLoggedIn())
                {
                    var user = _memberManager.GetCurrentMemberAsync().Result;
                    if (user != null)
                    {
                        roles = _memberManager.GetRolesAsync(user).Result;
                        if (roles.Contains("ForumAdministrator"))
                        {
                            <a href="/createforum" class="nav-link" title="Create Forum" data-bs-toggle="modal" data-bs-target="#forumModal"><i class="fs-5 bi-folder me-3"></i><span class="d-none d-sm-inline">Create Forum</span></a>
                        }
                    }
                    <a href="@Url.SurfaceAction("Logout", "ForumsSurface")" class="nav-link" title="Logout"><i class="fs-5 bi-door-closed me-3"></i><span class="d-none d-sm-none d-md-inline">@Umbraco.GetDictionaryValueOrDefault("Forums.Signout", "Logout")</span></a>
                }
            </nav>
        </div>
        <div class="main bg-white" id="mediawiz-forums">
            <div id="pageErrors"></div>
            @RenderBody()
        </div>
    </div>
</div>

@if (roles.Contains("ForumAdministrator"))
{
    @await Component.InvokeAsync("Forum",new {Template = "Create"})

}
@section MediaWizScripts {

    @*If theses scripts are included in your master template then comment them out or remove here*@

    <script src="https://cdnjs.cloudflare.com/ajax/libs/jquery-validate/1.19.3/jquery.validate.min.js" type="text/javascript"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/jquery-validation-unobtrusive/3.2.12/jquery.validate.unobtrusive.min.js" integrity="sha512-o6XqxgrUsKmchwy9G5VRNWSSxTS4Urr4loO6/0hYdpWmFUfHqGzawGxeQGMDqYzxjY9sbktPbNlkIQJWagVZQg==" crossorigin="anonymous" referrerpolicy="no-referrer" type="text/javascript"></script>

    <script src="/scripts/tinymce/tinymce.min.js" type="text/javascript"></script>
    <script src="/scripts/mediawiz.forums.min.js" referrerpolicy="origin" type="text/javascript"></script>
    <script type="text/javascript">
        var MediaWiz = MediaWiz || { };
        MediaWiz.returnUrl = '@TempData["returnUrl"]';
        MediaWiz.tools = MediaWiz.tools + "| emoticons ";
        if ('@allowimages'.toLowerCase() === 'true') {
            MediaWiz.tools = MediaWiz.tools + "| image ";
        }
        // Toggle sidebar collapse
        document.getElementById('toggleWizBtn').addEventListener('click', function () {
            document.getElementById('sidebar-forum').classList.toggle('collapsed');
        });

    </script>
    <renderstoredcontent asp-key="script-block"></renderstoredcontent>
}

@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<MediaWiz.Forums.ViewModels.SearchViewModel>
@using MediaWiz.Forums.Extensions
@using Umbraco.Extensions
@{
    Layout = "forumMaster.cshtml";

    int.TryParse(Context.Request.Query["page"], out var pagemum);
    if (pagemum == 0)
    {
        pagemum = 1;
    }
    var pageSize = Model.HasValue("intPageSize") ? Model.Value<int>("intPageSize") : 10;
    var totalPages = (int)Math.Ceiling((double)Model.TotalResults / (double)pageSize);
    ViewBag.Page = pagemum;
    ViewBag.TotalPages = totalPages;
}
<div class="wiz-forum-info">
    <div class="page-header">
        <h3>@Model.Value("title")</h3>
    </div>
    <div class="forum-intro">
        @await Component.InvokeAsync("Topics",new {Template = "ActiveSince"})
    </div>
</div>
<div>
    @if (Model.PagedResult.Any())
    {
        <div class="wiz-topics">
            <div class="d-flex flex-row flex-wrap p-2 color_dark bold">
                <div class="col-6">@Umbraco.GetDictionaryValueOrDefault("Forums.Topic", "Topic")</div>
                <div class="col-3">@Umbraco.GetDictionaryValueOrDefault("Forums.Forum", "Forum")</div>
                <div class="col-1">@Umbraco.GetDictionaryValueOrDefault("Forums.Replies", "Replies")</div>
                <div class="col-1">@Umbraco.GetDictionaryValueOrDefault("Forums.Views", "Views")</div>
                <div class="col-1">@Umbraco.GetDictionaryValueOrDefault("Forums.Activity", "Activity")</div>
            </div>
            <div class="wiz-body">
                @foreach (var result in Model.PagedResult)
                {
                    var post = Umbraco.Content(result.Id);
                    @await Component.InvokeAsync("Posts", new { Template = "DisplayTopic", Model = post, showTitle = true, activeTopics = true})

                }
                @if (totalPages > 1)
                {
                    @await Component.InvokeAsync("Navigation",new {Template = "PagerView", Model = Model})
                }
            </div>

        </div>

    }
    else
    {
        <p>@Umbraco.GetDictionaryValueOrDefault("Forums.NoTopics", "No active Topics") </p>
    }
</div>

<storecontent asp-key="script-block">
    <script>
        $(document).ready(function () {
            $("#active-since").on("change", function () {
                $("#topics-since").submit();
            });
            $("#active-filter").on("change", function () {
                $("#topics-since").submit();
            });
            MediaWiz.InitTinyMce("textarea.new-post");
        });
    </script>
</storecontent>

@using MediaWiz.Forums.Extensions
@using Umbraco.Extensions
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage

@{

    Layout = "forumMaster.cshtml";
    var test = Context.Request.Query["emailconfirmed"];
    if(!string.IsNullOrWhiteSpace(test) && test == "true")
    {
        var msg = Umbraco.GetDictionaryValueOrDefault("Forums.EmailConfirmed", "Email successfully confirmed");
        <storecontent asp-key="script-block">
            <script>
                $(document).ready(function () {
                    createAlert('','Nice Work!','@msg','success',true,true,'pageMessages');
                });
            </script>
        </storecontent>
    }
}
<div id="pageMessages"></div>
@if (Model.Value<bool>("isActive"))
{
    <div class="row" id="fInfo">
        <div class="col">
            @await Component.InvokeAsync("Forum",new {Template = "Info"})
        </div>
    </div>
    <div class="row" id="fForums">
        <div class="col">
            @await Component.InvokeAsync("Forum",new {Template = "List"})
        </div>
    </div>
    <div class="row" id="fTopics">
        <div class="col" >
            @await Component.InvokeAsync("Topics",new {Template = "List"})
        </div>
    </div>
    <div class="row" id="fPostForm">
        <div class="col">
            @await Component.InvokeAsync("Topics",new {Template = "Create"})
        </div>
    </div>
    <storecontent asp-key="script-block">
        <script>
            $(document).ready(function () {
                if(document.getElementsByClassName("new-post"))
                    {MediaWiz.InitTinyMce("textarea.new-post");}
            });
        </script>
    </storecontent>


}
else
{
    <div class="row" id="fInfo">
        <div class="col">
            <h5>No Active Forums!</h5>
        </div>
    </div>
}

@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage
@using MediaWiz.Core.Services
@using MediaWiz.Forums.Extensions
@using Umbraco.Cms.Infrastructure.Scoping

@inject IScopeProvider _ScopeProvider
@{
    Layout = "forumMaster.cshtml";

    int nodeId = Umbraco.AssignedContentItem.Id;
    string cookieName = $"PageView_{nodeId}";
    if (!Context.Session.Keys.Contains(cookieName))
    {
        new ForumViewCounterService(_ScopeProvider).RecordView(nodeId);

        Context.Session.Set(cookieName, new byte[] { 1 });
    }

}
<div>
    @await Component.InvokeAsync("Topics",new {Template = "DisplayThread"})
</div>
<div class="modal modal-xl fade" id="editPostModal" tabindex="-1" aria-labelledby="editPostModalLabel" aria-hidden="true">
    <div class="modal-dialog modal-lg">
        <div class="modal-content">
            <div class="modal-header">
                <h5 class="modal-title" id="editPostModalLabel">Edit Post</h5>
                <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
            </div>
            <div id="partial-form" style="padding:0.5em"></div>
        </div>
    </div>
</div>
<storecontent asp-key="script-block">
    <script>
        $(document).ready(function() {
            MediaWiz.InitTinyMce("textarea.new-post");
            $("#thread-sort").on("change",function() {
                $.ajax({
                    url: '@Url.Action("Sort", "ForumsSurface")',
                    type: 'POST',
                    contentType: 'application/json',
                    data: JSON.stringify({
                        "sort": this.value
                    }),
                    // other settings
                    success: function(data) {
                        if (data.success) {
                            location.href = data.message;
                        }
                    },
                    error: function(jqXHR, exception) {
                        createAlert('','Nice Work!',exception,'danger',true,true,'pageMessages');
                    }
                });
            });
        });

    </script>
</storecontent>

@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<MediaWiz.Forums.ViewModels.SearchViewModel>
@using MediaWiz.Forums.Interfaces
@using System.Text.RegularExpressions
@using Umbraco.Cms.Core.Security
@using Umbraco.Extensions
@inject IForumCacheService _forumCache
@inject IMemberManager _memberManager
@inject ForumSearchService SearchService

@{ 
    Layout = "forumMaster.cshtml";
    var currentUser = _memberManager.GetUserAsync(Context.User).Result;
    IList<string> roles = new List<string>();
    if (currentUser != null)
    {
        roles = _memberManager.GetRolesAsync(currentUser).Result;
    }
    int.TryParse(Context.Request.Query["page"], out var pagenum);
    if (pagenum == 0)
    {
        pagenum = 1;
    }
    var pageSize = Model.HasValue("intPageSize") ? Model.Value<int>("intPageSize") : 10;
    var totalPages = (int)Math.Ceiling((double)Model.TotalResults / (double)pageSize);
    ViewBag.Page = pagenum;
    ViewBag.TotalPages = totalPages;
    var results = Model.RawResult;
}
<div class="wiz-forum-info">
    <div class="page-header">
        <h3>@Model.Value("title")</h3>
    </div>
    <div class="forum-intro">
        @await Component.InvokeAsync("Forum", new { Template = "Search" })
    </div>
</div>

<div class="row">
    @if (results == null || !results.Any())
    {
        @if (!string.IsNullOrWhiteSpace(Model.query))
        {
            var suggestions = SearchService.GetSuggestions(Model.query);
            <p>No results found. Did you mean:</p>
            <ul class="list-unstyled">
                @foreach (var s in suggestions)
                {
                    <li><a href="@s.Url">@s.Subject</a></li>
                }
            </ul>
        }
    }
    else
    {
        <ul class="list-unstyled">
            <li class="row justify-content-end">
                <div class="col-md-3">
                    <select id="searchWhere" name="searchWhere" class="form-select form-select-sm me-2">
                        <option value="any">@Umbraco.GetDictionaryValueOrDefault("Forums.Search.sortBy.Relevence", "Relevence")</option>
                        <option value="open">@Umbraco.GetDictionaryValueOrDefault("Forums.Search.sortBy.Newest", "Newest")</option>
                        <option value="closed">@Umbraco.GetDictionaryValueOrDefault("Forums.Search.sortBy.Oldest", "Oldest")</option>
                    </select>
                </div>
            </li>
            @foreach (var r in results)
            {
                <li>
                    <a href="@r.Url">@r.Subject</a><br />
                    @Html.Raw(r.MessageSnippet)<br />
                    <small>Score: @r.Score (@r.ScoreExplanation)</small>
                    <hr />
                </li>
            }
        </ul>
    }
    @if (totalPages > 1)
    {
        @await Component.InvokeAsync("Navigation", new { Template = "PagerView", Model = Model })
    }
</div>

@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage
@using MediaWiz.Forums.Extensions
@using Umbraco.Extensions



@{
    Layout = "forumMaster.cshtml";
}

<storecontent asp-key="css-block">
    <meta name="robots" content="noindex,nofollow" />
</storecontent>

<div class="wiz-forum-info">
    <div class="page-header">
        <h3>@Model.Value("title")</h3>
    </div>
    <div class="forum-intro">
        @Html.Raw(Model.Value("message"))
    </div>
</div>
@await Component.InvokeAsync("ForumMembership", new { Template = "Login" })
<storecontent asp-key="script-block">
    <script type="text/javascript" src="/umbraco/surface/JavascriptSurface/LoadResources/?keys=Forums.CaptchaErrMsg"></script>
    <script id="login-v">
        $.fn.clearValidation = function(){var v = $(this).validate();$('[name]',this).each(function(){v.successList.push(this);v.showErrors();});v.resetForm();v.reset();};

        $(document).ready(function() {
            document.getElementById("Captcha").focus();
            if ('@Model.Value("useCaptcha")' !== 'True') {
                $('#login-submit').show();
            }
        });

        $('#Captcha').on("keyup",function (event) {
                    if (event.which == 13 || event.which == 13) {
                        $("#btn-captcha").trigger("click");
                        event.preventDefault();
                        return false;
                    }
                });
        $(document).on('click', "#btn-captcha", function (e) {

            e.preventDefault();
            MediaWiz.captchaCheck($("#Captcha").val(), function(data) {
                if (data) {
                    $("#captcha-check").hide();
                    $('#login-form-id').show();
                    $("#login-form-id").clearValidation();
                } else {
                    $("#Captcha").val("");
                    $("#Captcha").attr("placeholder", local.ForumsCaptchaErrMsg);
                }
            });
        });
        $(document).on("click","#captcha-refresh", function(e) {
            e.preventDefault();
            $.ajax({
                url: "/umbraco/surface/ForumsSurface/RefreshCaptcha",
                success: function (data) {
                    $("#captchaimage-div").html(data);
                }
            });
        });
    </script>
</storecontent>

@using Umbraco.Extensions
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage

@{
    Layout = "forumMaster.cshtml";

    int.TryParse(Context.Request.Query["page"], out var pagenum);
    if (pagenum == 0)
    {
        pagenum = 1;
    }
    var pageSize = Model.HasValue("intPageSize") ? Model.Value<int>("intPageSize") : 10;
    ViewBag.Page = pagenum;
    var isLoggedIn = Context.User?.Identity?.IsAuthenticated ?? false;
}
<storecontent asp-key="css-block">
    <meta name="robots" content="noindex,nofollow" />
</storecontent>
@if (isLoggedIn)
{
    <div class="wiz-forum-info">
        <div class="page-header">
            <h3>@Model.Value("title")</h3>
        </div>
        <div class="forum-intro">
            @Html.Raw(Model.Value("message"))
        </div>
    </div>
    <div class="row">
        <div class="col-12">
            @await Component.InvokeAsync("ForumMembership",new {Template = "ListMembers", PageSize = pageSize})

        </div>
    </div>
}

@using System.Text.RegularExpressions
@using MediaWiz.Forums.Extensions
@using Umbraco.Extensions
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage

@{
    Layout = "forumMaster.cshtml";
}
<storecontent asp-key="css-block">
    <meta name="robots" content="noindex,nofollow" />
</storecontent>

<div class="wiz-forum-info">
    <div class="page-header">
        <h3>@Model.Value("title")</h3>
    </div>
    <div class="forum-intro">
        @{
            var res = Regex.Match(Context.Request.Query["user"].ToString(), @"^\d+$");
            if (res.Success)
            {

            }
            else
            {
                @Html.Raw(Model.Value("message"))
            }
        }

    </div>
</div>
@await Component.InvokeAsync("ForumMembership",new {Template = "EditProfile",qryUser = Context.Request.Query["user"].ToString()})
<storecontent asp-key="script-block">
    <script id="profile">
        (function () {
          'use strict'

          // Fetch all the forms we want to apply custom Bootstrap validation styles to
          var forms = document.querySelectorAll('.needs-validation')

          // Loop over them and prevent submission
          Array.prototype.slice.call(forms)
            .forEach(function (form) {
              form.addEventListener('submit', function (event) {
                if (!form.checkValidity()) {
                  event.preventDefault()
                  event.stopPropagation()
                }

                form.classList.add('was-validated')
              }, false)
            })
        })();

        $('.nav-tabs button').on('shown.bs.tab', function (event) {

            var x = $(event.target).text();         // active tab
            var y = $(event.relatedTarget).text();  // previous tab console.log($(event));
            if (x === "Files") {
                $("#nav-files").load("/memberfiles/" + $("#nav-files").data("id"));
            }
        });
    </script>
</storecontent>

